INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261107-senate-counts', 'colom-lead-2010-votes-mississippi-affidavit-ballots-alaska-peltola-74-percent', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Colom''s Mississippi lead reaches 2,010 votes as counties work through affidavit ballots, and Alaska''s Senate race stalls at fewer than 700 votes', 'Mississippi counties must certify by Friday, Nov. 13. In Alaska, about three-quarters of ballots were counted as of Friday, Nov. 6, and any ranked-choice tally will not come before Wednesday, Nov. 18.', 'Democrat Scott Colom led Republican Sen. Cindy Hyde-Smith by 2,010 votes in Mississippi on Friday, Nov. 6. The Mississippi Free Press, citing an Associated Press update at 11:36 a.m., put the count at 467,066 to 465,056, or 49.1% to 48.8%. The race had not been called.

The lead was 1,813 votes on Thursday evening, Nov. 5, Democracy Docket reported, so it grew by about 200 votes overnight. Turnout has passed 950,000 votes, compared with about 710,000 in the 2022 midterms, according to Democracy Docket.

## Where the count stands

The remaining votes are mostly affidavit ballots, cast by voters whose eligibility must be checked, plus mail ballots still arriving. The Free Press reported these county figures on Friday:

- **DeSoto County:** about 2,100 affidavit ballots, with review and counting expected on Wednesday, Nov. 11, or Thursday, Nov. 12.
- **Harrison County:** 1,448 affidavit ballots. The election commission meets on Tuesday, Nov. 10, to decide which to accept.
- **Hinds County:** still counting affidavits precinct by precinct. One district had finished only 5 of its 14 precincts.

Tuesday, Nov. 10, is also the last day for mail ballots postmarked by Election Day to arrive, and the deadline for affidavit voters to show an ID at their circuit clerk''s office. Counties must certify by Friday, Nov. 13. Mississippi has no recount law, CBS News noted.

## Disputes over the process

The National Republican Senatorial Committee has asked counties to separate and preserve affidavit ballots. Colom''s lawyers answered that doing so would violate Mississippi voters'' rights and state election law, the Free Press reported. In DeSoto County, the ACLU said in a letter that the county was not meeting public-access rules. A county commissioner said observers would watch from an adjoining room, following the secretary of state''s direction.

On Friday, Colom said Secretary of State Michael Watson''s use of the credit agency Experian to check voter rolls had moved voters to inactive status and added to the ballot problems, according to Democracy Docket. Mississippi Republican Party chair Mike Hurst said on Thursday that his party would challenge ballots "if and when" evidence of problems emerged.

## Alaska

In Alaska, Democrat Mary Peltola led Republican Sen. Dan Sullivan by fewer than 700 votes on Friday, a margin that had barely moved in more than 24 hours, Gray News reported. About 74% of ballots had been counted. If no candidate reaches 50%, ranked-choice ballots will be redistributed, but not before Wednesday, Nov. 18. "It will be weeks," Peltola said.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Mississippi_River_in_Natchez,_Mississippi_LCCN2010630373.tif/lossy-page1-1280px-Mississippi_River_in_Natchez,_Mississippi_LCCN2010630373.tif.jpg', 'The Mississippi River at Natchez, Mississippi (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-07.sql', 8, 0, 'newsroom-assistant', '2026-11-07T10:50:00.000Z', '2026-11-07T10:50:00.000Z');
