INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261107-arch-blocked', 'judge-chutkan-blocks-trump-arch-memorial-circle-14-days-dc-virginia-lawsuit', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Judge Chutkan blocks work on Trump''s 250-foot arch for 14 days, hours after a federal panel approved it', 'The District of Columbia and Virginia sued to stop the memorial arch planned for Memorial Circle near Arlington National Cemetery. The government must report on its compliance on Monday, Nov. 9.', 'A federal judge has barred the Trump administration from breaking ground on President Trump''s planned memorial arch for 14 days.

U.S. District Judge Tanya Chutkan issued the temporary restraining order late on Thursday, Nov. 5, the Associated Press reported. Earlier that day, the National Capital Planning Commission had approved the 250-foot arch by an 8-4 vote after a hearing of about nine and a half hours. The arch is planned for Memorial Circle, near Arlington National Cemetery.

## Who sued, and why

The District of Columbia and Virginia brought the case. They argued that construction would disrupt traffic, interfere with emergency mutual-aid calls between the two jurisdictions and leave D.C. transportation staff with costs they could not recover for managing detours and crashes, the AP reported.

Chutkan found that the harm from starting construction right away was certain. She also doubted the administration''s legal footing. The administration has pointed to a 1925 law, and the judge said it was highly improbable that a 100-year-old statute would authorize a 250-foot arch, according to the AP.

## The vote and the politics

The commission''s vote split largely along federal and local lines. Its Trump-appointed chairman, Mark Paoletta, backed the project, and most of the members who voted no represent Washington, the AP reported. D.C. Council Chairman Phil Mendelson, who sits on the commission, said Congress has neither approved the arch nor paid for it. Rep. Jared Huffman of California, who is expected to chair the House Natural Resources Committee in the new Democratic majority, called the arch illegal.

The administration says Congress already cleared the way for a memorial at Memorial Circle. The government must file a status report on Monday, Nov. 9, showing that it is complying with the order.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Memorial_amphitheater_at_arlington_national_cemetery.tif/lossy-page1-1280px-Memorial_amphitheater_at_arlington_national_cemetery.tif.jpg', 'Memorial Amphitheater at Arlington National Cemetery under construction, about 1916-17 (file). Photo: National Photo Company / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-07.sql', 7, 0, 'newsroom-assistant', '2026-11-07T10:50:00.000Z', '2026-11-07T10:50:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261107-arch-blocked-src1', 'bd-20261107-arch-blocked', 'Federal judge orders 14-day delay on any work beginning on Trump''s monumental arch', 'https://www.walb.com/2026/11/06/federal-judge-orders-14-day-delay-any-work-beginning-trumps-monumental-arch/', 'Associated Press via WALB', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-07T10:50:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-07. Editor to confirm.', 'newsroom-assistant', '2026-11-07T10:50:00.000Z');
