INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261107-celtics-hornets', 'celtics-rout-hornets-119-80-nba-cup-tatum-34-points', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Tatum scores 34 as the Celtics rout the Hornets 119-80 in Charlotte to stay unbeaten in NBA Cup play', 'Boston made 17 of 31 3-pointers in the first half on Friday, Nov. 6, and improved to 7-2. Charlotte has lost six straight.', 'The Celtics ran away from the Charlotte Hornets early and won 119-80 at Spectrum Center on Friday, Nov. 6, in an Emirates NBA Cup group game.

Jayson Tatum led Boston with 34 points, 9 assists and 8 rebounds, and he made five 3-pointers, according to ESPN and NBA.com. Derrick White added 18 points.

## How it got away

Boston made 17 of its 31 3-point attempts in the first half, ESPN reported. Charlotte shot 28% from the field before halftime and turned the ball over eight times. Naz Reid led the Hornets with 14 points.

Charlotte also lost Brandon Miller, who left in the second quarter with right groin soreness and did not return. He had 8 points on 3-of-10 shooting. The Hornets were already without Kon Knueppel, who reinjured his hamstring on Wednesday, Nov. 4, at Brooklyn in his first game of the season.

## Where things stand

The Celtics are 7-2 and 2-0 in NBA Cup play. The Hornets fell to 3-7, 0-2 in the Cup, and have lost six straight. Boston plays at Milwaukee on Sunday, Nov. 8.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/b/b6/Mint_Museum_in_uptown_Charlotte,_North_Carolina.jpg', 'The Mint Museum in uptown Charlotte, North Carolina (file). Photo: Bz3rk via Wikimedia Commons, CC BY-SA 3.0', 'licensed', 'newsroom', 'content/2026-11-07.sql', 6, 0, 'newsroom-assistant', '2026-11-07T10:50:00.000Z', '2026-11-07T10:50:00.000Z');
