INSERT OR IGNORE INTO story_events (id, story_id, from_status, to_status, actor, note, created_at) VALUES ('bd-20261107-celtics-hornets-ev1', 'bd-20261107-celtics-hornets', NULL, 'EDITORIAL_REVIEW', 'newsroom-assistant', 'Drafted from attributed reporting and primary sources; awaiting editor approval', '2026-11-07T10:50:00.000Z');
INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261107-nba-friday', 'luka-doncic-53-lakers-beat-blazers-lebron-james-8-points-cavaliers-beat-76ers', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Doncic scores 53 as the Lakers beat the Blazers, and LeBron James is held to 8 points in his return to Cleveland', 'Doncic has four straight 40-point games, a Lakers streak matched only by Kobe Bryant, Elgin Baylor and George Mikan. The Cavaliers beat the 76ers 119-95 on Friday, Nov. 6.', 'Luka Doncic scored a season-high 53 points as the Los Angeles Lakers beat the Portland Trail Blazers 124-118 at Crypto.com Arena on Friday, Nov. 6, ESPN reported.

It was Doncic''s fourth straight game with at least 40 points. That ties a Lakers mark shared by Kobe Bryant, Elgin Baylor and George Mikan, according to ESPN. He also hit a 62-foot shot at the halftime buzzer that sparked the Lakers'' comeback. Doncic is averaging a career-high 40.1 points a game, and no player has averaged 40 for a season since Wilt Chamberlain in 1962-63. Blazers coach Micah Nori said Doncic "is the MVP right now."

## LeBron''s return to Cleveland

In Cleveland, the Cavaliers beat the Philadelphia 76ers 119-95 at Rocket Arena, ending Philadelphia''s five-game winning streak. It was LeBron James'' first game in Cleveland as a 76er. He left the Lakers in June.

James scored 8 points on 3-of-12 shooting with 7 rebounds, 3 assists and 6 turnovers, Türkiye Today reported. ESPN said it was only the 10th regular-season game in his 24 seasons in which he scored in single digits. Accounts of the crowd differed: Türkiye Today described a largely warm welcome with scattered boos, while ESPN reported boos as he left the court late in the game.

Donovan Mitchell led Cleveland with 23 points, 8 assists and 7 rebounds, Evan Mobley scored 22, and James Harden added 17. Jaylen Brown had 20 for Philadelphia, and Joel Embiid missed all nine of his shots from the field. The Cavaliers are 5-4, and the 76ers are 8-2.

## Elsewhere on Friday

Ajay Mitchell scored a career-high 35 points as Oklahoma City beat Memphis 128-97, NBA.com reported. Atlanta beat Washington 139-132, Toronto beat Milwaukee 121-107, Dallas beat Utah 112-100, Minnesota beat New Orleans 115-109 and San Antonio beat Sacramento 124-109.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Skyline_view_of_Los_Angeles,_California_LCCN2013631687.tif/lossy-page1-1280px-Skyline_view_of_Los_Angeles,_California_LCCN2013631687.tif.jpg', 'The Los Angeles skyline, 2013 (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-07.sql', 5, 0, 'newsroom-assistant', '2026-11-07T10:50:00.000Z', '2026-11-07T10:50:00.000Z');
