INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261107-wild-sharks', 'wild-beat-sharks-4-1-kaprizov-16th-goal-quinn-hughes', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Kaprizov scores his NHL-leading 16th goal and adds three assists as the Wild beat the Sharks 4-1', 'Minnesota has won three straight and is 6-0-1 in its past seven games after the Friday, Nov. 6, win in St. Paul. San Jose has lost four in a row.', 'Kirill Kaprizov had a goal and three assists as the Minnesota Wild beat the San Jose Sharks 4-1 at Grand Casino Arena in St. Paul on Friday, Nov. 6, NHL.com reported.

Kaprizov opened the scoring on a 5-on-3 power play in the first period for his 16th goal, the most in the league. Macklin Celebrini tied the game for San Jose midway through the second period, but Maxim Shabanov put Minnesota back ahead on a power play about two minutes later.

Quinn Hughes scored in the third period and finished with a goal and two assists. Zach Bogosian added his first goal of the season. Jesper Wallstedt made 23 saves for the win, and Yaroslav Askarov stopped 25 shots for the Sharks.

## Where things stand

The Wild are 12-3-3, with three straight wins and a 6-0-1 record in their past seven games. The Sharks fell to 7-10-1. They have lost four straight and six of seven, and they held a players-only meeting on Wednesday, Nov. 4, after a 7-2 loss to the Los Angeles Kings, according to NHL.com.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Panoramic_view_of_St._Paul,_Minn_LCCN2007662333.tif/lossy-page1-1280px-Panoramic_view_of_St._Paul,_Minn_LCCN2007662333.tif.jpg', 'Panoramic view of St. Paul, Minnesota, 1911 (file). Photo: Haines Photo Co. / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-07.sql', 4, 0, 'newsroom-assistant', '2026-11-07T10:50:00.000Z', '2026-11-07T10:50:00.000Z');
