INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261107-patriots-packers-final-report', 'patriots-packers-final-injury-report-aj-brown-out-hunter-henry-questionable-maye-full', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'A.J. Brown is ruled out and Hunter Henry is questionable for the Patriots'' game against the Packers on Sunday, Nov. 8', 'Drake Maye practiced fully all week with a right shoulder injury and has no game status. Green Bay has ruled out Micah Parsons and four others.', 'The Patriots will play the Green Bay Packers at Gillette Stadium on Sunday, Nov. 8, without wide receiver A.J. Brown. The team ruled Brown out with ankle and knee injuries on its final injury report, released on Friday, Nov. 6. Running back TreVeyon Henderson is also out with an illness, according to Patriots.com.

Quarterback Drake Maye, who has a right shoulder injury, took part fully in practice on Wednesday, Thursday and Friday and has no game status, which means he is expected to play.

## Questionable for New England

Seven Patriots are listed as questionable:

- TE Hunter Henry (foot)
- S Kevin Byard III (chest)
- CB Carlton Davis III (neck)
- WR Mack Hollins (calf)
- T Morgan Moses (foot)
- S Brenden Schooler (hamstring)
- OL Greg Van Roten (hamstring)

Hollins and Van Roten both returned to practice from injured reserve ahead of the Sunday game, Yahoo Sports reported.

## Green Bay''s report

The Packers ruled out five players: edge rusher Micah Parsons (knee), linebacker Zaire Franklin (shin), offensive lineman Travis Glover (knee), center Sean Rhyan (ankle) and tight end Josh Whyle (concussion). Running backs Chris Brooks and MarShawn Lloyd and cornerback Keisean Nixon are questionable.

Parsons, coming back from a torn ACL last season, is on the designated-for-return list and was limited in practice all three days, Sports Illustrated reported. Nixon was limited on Friday but was seen running and catching passes in warmups. Asked about it, he joked, "That was AI."', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/a/a1/Gillette_Stadium_November_2012_2013_01_121111-F-PB262-814.jpg', 'A C-5 Galaxy flies over Gillette Stadium before a Patriots game, Nov. 11, 2012 (file). Photo: Senior Airman Kelly Galloway / U.S. Air Force via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-07.sql', 5, 0, 'newsroom-assistant', '2026-11-07T10:50:00.000Z', '2026-11-07T10:50:00.000Z');
